import textwrap
from query import run_query

def setup_module(m):
    open('pets.csv','w').write(textwrap.dedent('''\
    name,species,age,weight\n    Rex,dog,4,20.5\n    Whiskers,cat,7,4.2\n    Bubbles,fish,1,0.1\n    Fang,dog,2,18.0\n    Milo,cat,3,5.0\n    '''))

def test_star():
    assert len(run_query('SELECT * FROM pets')) == 5

def test_projection_order():
    rows = run_query('SELECT age, name FROM pets LIMIT 2')
    assert rows == [{'age': 4, 'name': 'Rex'}, {'age': 7, 'name': 'Whiskers'}]

def test_where_and_order():
    rows = run_query("SELECT name FROM pets WHERE species = 'dog' ORDER BY age DESC")
    assert [r['name'] for r in rows] == ['Rex', 'Fang']

def test_numeric_compare():
    rows = run_query('SELECT name FROM pets WHERE weight >= 5.0 ORDER BY name')
    assert [r['name'] for r in rows] == ['Fang', 'Milo', 'Rex', 'Whiskers']

def test_limit_offset():
    rows = run_query('SELECT name FROM pets ORDER BY name LIMIT 2 OFFSET 1')
    assert [r['name'] for r in rows] == ['Fang', 'Milo']

def test_bad_column():
    try:
        run_query('SELECT nope FROM pets')
        assert False
    except KeyError:
        pass

