import csv


# ---------------------------------------------------------------------------
# Tokenizer
# ---------------------------------------------------------------------------

class Token:
    def __init__(self, kind, value):
        self.kind = kind      # KEYWORD, IDENT, STRING, NUMBER, OP, PUNCT, STAR
        self.value = value

    def __repr__(self):
        return f'Token({self.kind}, {self.value!r})'


KEYWORDS = {'SELECT', 'FROM', 'WHERE', 'ORDER', 'BY', 'LIMIT', 'OFFSET', 'ASC', 'DESC'}


def tokenize(text):
    tokens = []
    i, n = 0, len(text)
    while i < n:
        c = text[i]
        if c.isspace():
            i += 1
            continue
        if c == "'":  # quoted string literal; may contain spaces
            j = i + 1
            buf = []
            while j < n and text[j] != "'":
                buf.append(text[j])
                j += 1
            if j >= n:
                raise SyntaxError(f'Unterminated string literal at position {i}')
            tokens.append(Token('STRING', ''.join(buf)))
            i = j + 1
            continue
        if c.isalpha() or c == '_':
            j = i
            while j < n and (text[j].isalnum() or text[j] == '_'):
                j += 1
            word = text[i:j]
            upper = word.upper()
            if upper in KEYWORDS:
                tokens.append(Token('KEYWORD', upper))
            else:
                tokens.append(Token('IDENT', word))
            i = j
            continue
        if c.isdigit():
            j = i
            while j < n and text[j].isdigit():
                j += 1
            if j + 1 < n and text[j] == '.' and text[j + 1].isdigit():
                j += 1
                while j < n and text[j].isdigit():
                    j += 1
                tokens.append(Token('NUMBER', float(text[i:j])))
            else:
                tokens.append(Token('NUMBER', int(text[i:j])))
            i = j
            continue
        if c in '<>!=':
            if i + 1 < n and text[i + 1] == '=':
                tokens.append(Token('OP', c + '='))
                i += 2
            elif c != '!':
                tokens.append(Token('OP', c))
                i += 1
            else:
                raise SyntaxError(f'Unexpected character ! at position {i}')
            continue
        if c == '*':
            tokens.append(Token('STAR', '*'))
            i += 1
            continue
        if c == ',':
            tokens.append(Token('PUNCT', ','))
            i += 1
            continue
        raise SyntaxError(f'Unexpected character {c!r} at position {i}')
    return tokens


# ---------------------------------------------------------------------------
# Parser / evaluator
# ---------------------------------------------------------------------------

def _coerce(value):
    """Convert a CSV string to int or float when possible."""
    try:
        return int(value)
    except ValueError:
        pass
    try:
        return float(value)
    except ValueError:
        return value


def _compare(cell, op, literal):
    left = cell if isinstance(literal, (int, float)) else str(cell)
    if op == '=':
        return left == literal
    if op == '!=':
        return left != literal
    if op == '<':
        return left < literal
    if op == '>':
        return left > literal
    if op == '<=':
        return left <= literal
    if op == '>=':
        return left >= literal
    raise ValueError(f'Unknown operator {op!r}')


class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def next(self):
        tok = self.peek()
        if tok is None:
            raise SyntaxError('Unexpected end of query')
        self.pos += 1
        return tok

    def expect_keyword(self, kw):
        tok = self.next()
        if tok.kind != 'KEYWORD' or tok.value != kw:
            raise SyntaxError(f'Expected {kw}, got {tok.value!r}')

    def run(self, rows):
        self.expect_keyword('SELECT')

        columns = []          # list of column names, or ['*']
        if self.peek() and self.peek().kind == 'STAR':
            self.next()
            columns = ['*']
        else:
            while True:
                tok = self.next()
                if tok.kind != 'IDENT':
                    raise SyntaxError(f'Expected column name, got {tok.value!r}')
                columns.append(tok.value)
                if self.peek() and self.peek().kind == 'PUNCT':
                    self.next()
                else:
                    break

        self.expect_keyword('FROM')
        table_tok = self.next()
        if table_tok.kind != 'IDENT':
            raise SyntaxError(f'Expected table name, got {table_tok.value!r}')

        where_pred = None
        order_col, order_desc = None, False
        limit = offset = None

        while self.peek() is not None:
            tok = self.next()
            if tok.kind != 'KEYWORD':
                raise SyntaxError(f'Unexpected token {tok.value!r}')
            if tok.value == 'WHERE':
                col = self.next()
                op = self.next()
                lit = self.next()
                if col.kind != 'IDENT' or op.kind != 'OP' or \
                        lit.kind not in ('STRING', 'NUMBER'):
                    raise SyntaxError('Malformed WHERE clause')
                key, oper = col.value, op.value
                where_pred = lambda row, k=key, o=oper, l=lit.value: _compare(row[k], o, l)
            elif tok.value == 'ORDER':
                self.expect_keyword('BY')
                col = self.next()
                if col.kind != 'IDENT':
                    raise SyntaxError(f'Expected column name after ORDER BY, got {col.value!r}')
                order_col = col.value
                if self.peek() and self.peek().kind == 'KEYWORD' and \
                        self.peek().value in ('ASC', 'DESC'):
                    order_desc = self.next().value == 'DESC'
            elif tok.value == 'LIMIT':
                num = self.next()
                if num.kind != 'NUMBER' or not isinstance(num.value, int):
                    raise SyntaxError('LIMIT requires an integer')
                limit = num.value
            elif tok.value == 'OFFSET':
                num = self.next()
                if num.kind != 'NUMBER' or not isinstance(num.value, int):
                    raise SyntaxError('OFFSET requires an integer')
                offset = num.value
            else:
                raise SyntaxError(f'Unexpected keyword {tok.value!r}')

        # --- execute ---
        result = [dict(r) for r in rows]

        if where_pred is not None:
            result = [r for r in result if where_pred(r)]

        if order_col is not None:
            try:
                result.sort(key=lambda r: (_coerce(r[order_col]),), reverse=order_desc)
            except KeyError as e:
                raise KeyError(f'Unknown column in ORDER BY: {e}') from e

        if offset is not None:
            result = result[offset:]
        if limit is not None:
            result = result[:limit]

        if columns != ['*']:
            projected = []
            for r in result:
                out = {}
                for c in columns:
                    out[c] = _coerce(r[c])   # raises KeyError on bad column
                projected.append(out)
            result = projected
        else:
            for r in result:
                for k in r:
                    r[k] = _coerce(r[k])

        return result


def run_query(sql, csv_path='pets.csv'):
    with open(csv_path, newline='') as f:
        reader = csv.DictReader(f)
        rows = [row for row in reader]
    return Parser(tokenize(sql)).run(rows)
